), documents as materialized (
  select code, name, indication, contraindication, performer, equipment, duration
  from public.byt_documents

  union all

  select code, name, indication, contraindication, performer, equipment, duration
  from public.bv115_documents
), incoming as materialized (
  select
    mappings.technical_code,
    mappings.expected_source_code,
    mappings.match_method,
    documents.code as document_code,
    documents.name as document_name,
    documents.indication,
    documents.contraindication,
    documents.performer,
    documents.equipment,
    documents.duration
  from mappings
  join documents on documents.code = mappings.document_code
)
update public.technical_procedures as target
set
  source_code = incoming.document_code,
  source_name = incoming.document_name,
  has_process = true,
  indication = case
    when coalesce(btrim(target.indication), '') in ('', '0', '#N/A')
      and coalesce(btrim(incoming.indication), '') not in ('', '0', '#N/A')
    then incoming.indication
    else target.indication
  end,
  contraindication = case
    when coalesce(btrim(target.contraindication), '') in ('', '0', '#N/A')
      and coalesce(btrim(incoming.contraindication), '') not in ('', '0', '#N/A')
    then incoming.contraindication
    else target.contraindication
  end,
  performer = case
    when coalesce(btrim(target.performer), '') in ('', '0', '#N/A')
      and coalesce(btrim(incoming.performer), '') not in ('', '0', '#N/A')
    then incoming.performer
    else target.performer
  end,
  equipment = case
    when coalesce(btrim(target.equipment), '') in ('', '0', '#N/A')
      and coalesce(btrim(incoming.equipment), '') not in ('', '0', '#N/A')
    then incoming.equipment
    else target.equipment
  end,
  duration = case
    when coalesce(btrim(target.duration), '') in ('', '0', '#N/A')
      and coalesce(btrim(incoming.duration), '') not in ('', '0', '#N/A')
    then incoming.duration
    else target.duration
  end,
  updated_at = now()
from incoming
where target.code = incoming.technical_code
  and coalesce(target.source_code, '') = incoming.expected_source_code
  and (
    target.source_code is distinct from incoming.document_code
    or target.source_name is distinct from incoming.document_name
    or target.has_process is not true
    or (
      coalesce(btrim(target.indication), '') in ('', '0', '#N/A')
      and coalesce(btrim(incoming.indication), '') not in ('', '0', '#N/A')
    )
    or (
      coalesce(btrim(target.contraindication), '') in ('', '0', '#N/A')
      and coalesce(btrim(incoming.contraindication), '') not in ('', '0', '#N/A')
    )
    or (
      coalesce(btrim(target.performer), '') in ('', '0', '#N/A')
      and coalesce(btrim(incoming.performer), '') not in ('', '0', '#N/A')
    )
    or (
      coalesce(btrim(target.equipment), '') in ('', '0', '#N/A')
      and coalesce(btrim(incoming.equipment), '') not in ('', '0', '#N/A')
    )
    or (
      coalesce(btrim(target.duration), '') in ('', '0', '#N/A')
      and coalesce(btrim(incoming.duration), '') not in ('', '0', '#N/A')
    )
  );
